// Extract HTML from AI response
const aiResponse = $input.first().json.output;

// Extract HTML code from markdown code blocks
const htmlMatch = aiResponse.match(/```html\n([\s\S]*?)```/);
const rawHtml = htmlMatch ? htmlMatch[1] : aiResponse;

// Build complete HTML with Tailwind CDN
const completeHtml = `
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>UX Preview - ${$('Build Context').item.json.sessionId}</title>
    <script src="https://cdn.tailwindcss.com"></script>
</head>
<body>
    ${rawHtml}

    <!-- Version Watermark -->
    <div style="position: fixed; bottom: 10px; right: 10px; background: rgba(0,0,0,0.7); color: white; padding: 8px 12px; border-radius: 4px; font-size: 11px; font-family: monospace; z-index: 9999;">
        Session: ${$('Build Context').item.json.sessionId.slice(0, 12)}... | ${new Date().toLocaleTimeString()}
    </div>
</body>
</html>
`;

return {
  json: {
    html: completeHtml,
    rawHtml: rawHtml,
    sessionId: $('Build Context').item.json.sessionId,
    timestamp: new Date().toISOString(),
    inputType: $('Build Context').item.json.inputType
  }
};
